function validate([numbers]) {
  if (numbers.length < 2 || numbers.length > 50) return 'numbers needs 2 to 50 phone numbers.';
  for (const number of numbers) {
    if (number.length < 1 || number.length > 50) return 'Each phone number has 1 to 50 digits.';
    if (!/^[0-9]+$/.test(number)) return 'Phone numbers use only the digits 0 to 9.';
  }
  return null;
}

