function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const randomDigits = (length, digits) => Array.from({ length }, () => String(pick(0, digits - 1))).join('');
  let numbers;
  if (size === 'large') {
    // 50 numbers share an area code and each gets its own two-digit exchange, so none is a prefix of another.
    const area = randomDigits(pick(0, 20), 10);
    const exchanges = Array.from({ length: 100 }, (_, i) => String(i).padStart(2, '0'));
    numbers = [];
    for (let i = 0; i < 50; i++) {
      const exchange = exchanges.splice(pick(0, exchanges.length - 1), 1)[0];
      numbers.push(area + exchange + randomDigits(pick(0, 48 - area.length), 10));
    }
  } else {
    const digits = pick(2, 10);
    numbers = Array.from({ length: pick(2, 7) }, () => randomDigits(pick(1, 4), digits));
  }
  // Half of the inputs get a planted prefix: one number becomes a prefix or an extension of another.
  if (rand() < 0.5) {
    const from = pick(0, numbers.length - 1);
    let to = pick(0, numbers.length - 2);
    if (to >= from) to++;
    const source = numbers[from];
    numbers[to] = rand() < 0.5 ? source.slice(0, pick(1, source.length)) : (source + randomDigits(pick(0, 3), 10)).slice(0, 50);
  }
  return [numbers];
}
